import * as THREE from 'three';
import { describe, expect, it, vi } from 'vitest';
import { AssetManager, type TextureLoaderLike } from './AssetManager';
import { AudioManager, type AudioBackend } from './AudioManager';

const audioBuffer = () => ({} as AudioBuffer);

describe('AssetManager', () => {
  it('falls back when an optional texture is missing', async () => {
    const loader: TextureLoaderLike = { loadAsync: vi.fn().mockRejectedValue(new Error('404')) };
    const manager = new AssetManager(loader);
    const result = await manager.loadTexture({ key: 'missing', url: '/missing.png' });
    expect(result.fallback).toBe(true);
    expect(result.texture).toBeInstanceOf(THREE.Texture);
    expect(manager.getTexture('missing')).toBe(result.texture);
    manager.dispose();
  });

  it('reports texture progress through completion', async () => {
    const loader: TextureLoaderLike = { loadAsync: vi.fn().mockResolvedValue(new THREE.Texture()) };
    const manager = new AssetManager(loader);
    const ratios: number[] = [];
    await manager.loadTextures([{ key: 'a', url: '/a.png' }, { key: 'b', url: '/b.png' }], p => ratios.push(p.ratio));
    expect(ratios).toEqual([0, 0.5, 1]);
    manager.dispose();
  });
});

describe('AudioManager', () => {
  it('keeps missing optional audio silent', async () => {
    const backend: AudioBackend = { load: vi.fn().mockRejectedValue(new Error('404')), play: vi.fn() };
    const manager = new AudioManager(backend);
    manager.register({ id: 'missing-hit', url: '/missing.ogg', category: 'sfx' });
    const result = await manager.loadEvent('missing-hit');
    expect(result).toMatchObject({ loaded: false, fallback: true });
    expect(manager.play('missing-hit')).toBe(false);
    expect(backend.play).not.toHaveBeenCalled();
  });

  it('applies event, category and master volume', async () => {
    const play = vi.fn();
    const backend: AudioBackend = { load: vi.fn().mockResolvedValue(audioBuffer()), play };
    const manager = new AudioManager(backend);
    manager.register({ id: 'click', url: '/click.ogg', category: 'ui', volume: 0.5 });
    manager.setMasterVolume(0.5);
    manager.setCategoryVolume('ui', 0.8);
    await manager.loadEvent('click');
    expect(manager.play('click')).toBe(true);
    expect(play).toHaveBeenCalledWith(expect.anything(), { category: 'ui', volume: 0.2, loop: false });
  });

  it('reports progress when optional audio is missing', async () => {
    const backend: AudioBackend = {
      load: vi.fn().mockResolvedValueOnce(audioBuffer()).mockRejectedValueOnce(new Error('missing')),
      play: vi.fn(),
    };
    const manager = new AudioManager(backend);
    manager.registerMany([
      { id: 'music', url: '/music.ogg', category: 'music' },
      { id: 'ambient', url: '/missing.ogg', category: 'ambient' },
    ]);
    const ratios: number[] = [];
    const results = await manager.loadAll(p => ratios.push(p.ratio));
    expect(results.map(r => r.fallback)).toEqual([false, true]);
    expect(ratios).toEqual([0, 0.5, 1]);
  });
});
